            r_stop_q <= ctl_ho.CTRL.STOP.value;
        end
    end
    assign go_a   = ctl_ho.CTRL.GO.value && !r_go_q;
    assign stop_a = ctl_ho.CTRL.STOP.value && !r_stop_q;
    assign seed_a = ctl_ho.HASH_SEED.VALUE.value;

